import { getCustomerById, getOrdersByCustomerId } from "@/core/api";
import { CustomerProfile } from "@/components/admin/customers/CustomerProfile";
import { notFound } from "next/navigation";

interface PageProps {
  params: {
    id: string;
  };
}

export default async function CustomerPage({ params }: PageProps) {
  const { id } = await params;
  const customer = await getCustomerById(id);

  if (!customer) {
    notFound();
  }

  const customerOrders = await getOrdersByCustomerId(customer.id);

  return (
    <div className="flex-1 space-y-4 p-4 md:p-8 pt-6">
      <CustomerProfile customer={customer} orders={customerOrders} />
    </div>
  );
}

